const CATEGORY_PATH_SEPARATOR = '/';

export const categoryAncestorIds = (category: CategoryLike): string[] => {
  const ids = (category.parentCategoryTree ?? [])
    .map((record) => record.id)
    .filter((id): id is string => typeof id === 'string' && id.length > 0);
  if (ids[ids.length - 1] !== category.id) {
    ids.push(category.id);
  }
  return ids;
};
